import Foundation
import SpriteKit
import UIKit

// MARK: - Combat VFX Assets
//
// Slash effects: 6 frames per horizontal sheet.
// Hit effect: 9 frames in a 288x32 horizontal sheet.
//
// The PNG data is embedded directly so the current V3 command-line
// GitHub Actions build does not need a separate resource-copy step.

@MainActor
enum CombatVFXAssets {

    static let attack1SlashFrames: [SKTexture] =
        makeFrames(
            base64: "",
            frameCount: 6
        )

    static let attack2SlashFrames: [SKTexture] =
        makeFrames(
            base64: "",
            frameCount: 6
        )

    static let attack3SlashFrames: [SKTexture] =
        makeFrames(
            base64: "",
            frameCount: 6
        )

    static let strongSlashFrames: [SKTexture] =
        makeFrames(
            base64: "",
            frameCount: 6
        )

    static let criticalSlashFrames: [SKTexture] =
        makeFrames(
            base64: "",
            frameCount: 6
        )

    static let hitFrames: [SKTexture] =
        makeFrames(
            base64: "",
            frameCount: 9
        )

    static func slashFrames(
        for animation: HunterAttackAnimation
    ) -> [SKTexture] {
        switch animation {
        case .attack1:
            return attack1SlashFrames

        case .attack2:
            return attack2SlashFrames

        case .attack3:
            return attack3SlashFrames

        case .strong:
            return strongSlashFrames

        case .critical:
            return criticalSlashFrames
        }
    }

    private static func makeFrames(
        base64: String,
        frameCount: Int
    ) -> [SKTexture] {
        guard
            frameCount > 0,
            let data =
                Data(
                    base64Encoded: base64
                ),
            let image =
                UIImage(
                    data: data
                )
        else {
            return []
        }

        let sheet =
            SKTexture(
                image: image
            )

        sheet.filteringMode =
            .nearest

        let count =
            CGFloat(frameCount)

        return (0..<frameCount).map {
            index in

            let frame =
                SKTexture(
                    rect:
                        CGRect(
                            x:
                                CGFloat(index)
                                / count,
                            y: 0,
                            width:
                                1 / count,
                            height: 1
                        ),
                    in: sheet
                )

            frame.filteringMode =
                .nearest

            return frame
        }
    }
}
